<?php
require_once __DIR__ . '/layout.php';if(!leave_is_admin()){http_response_code(403);die('403 Forbidden: เฉพาะ Admin เท่านั้น');}
if($_SERVER['REQUEST_METHOD']==='POST'){leave_require_csrf();$action=(string)($_POST['action']??'');
 if($action==='type_quota'){$id=(int)($_POST['type_id']??0);$raw=trim((string)($_POST['default_quota_days']??''));if($raw===''){$stmt=$conn->prepare("UPDATE leave_types_master SET default_quota_days=NULL,updated_at=NOW() WHERE id=?");$stmt->bind_param('i',$id);}else{$quota=max(0,(float)$raw);$stmt=$conn->prepare("UPDATE leave_types_master SET default_quota_days=?,updated_at=NOW() WHERE id=?");$stmt->bind_param('di',$quota,$id);} $stmt->execute();$stmt->close();leave_flash('success','อัปเดตสิทธิ์เริ่มต้นแล้ว');leave_redirect('settings.php');}
 if($action==='balance'){$userId=(int)($_POST['user_id']??0);$fy=(int)($_POST['fiscal_year']??leave_fiscal_year());$typeId=(int)($_POST['leave_type_id']??0);$quota=max(0,(float)($_POST['quota_days']??0));$carried=(float)($_POST['carried_days']??0);$adjust=(float)($_POST['adjustment_days']??0);$note=trim((string)($_POST['note']??''));$by=(int)$_SESSION['user_id'];if($userId<=0||$typeId<=0) {leave_flash('error','กรุณาเลือกบุคลากรและประเภทการลา');leave_redirect('settings.php');}$stmt=$conn->prepare("INSERT INTO leave_balances(user_id,fiscal_year,leave_type_id,quota_days,carried_days,adjustment_days,note,updated_by) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE quota_days=VALUES(quota_days),carried_days=VALUES(carried_days),adjustment_days=VALUES(adjustment_days),note=VALUES(note),updated_by=VALUES(updated_by),updated_at=NOW()");$stmt->bind_param('iiidddsi',$userId,$fy,$typeId,$quota,$carried,$adjust,$note,$by);$stmt->execute();$stmt->close();leave_flash('success','บันทึกสิทธิ์วันลารายบุคคลแล้ว');leave_redirect('settings.php');}
}
$types=array();$res=$conn->query("SELECT * FROM leave_types_master ORDER BY sort_order,id");while($res&&$r=$res->fetch_assoc())$types[]=$r;$users=array();$res=$conn->query("SELECT id,fullname,department FROM users WHERE status='active' ORDER BY fullname");while($res&&$r=$res->fetch_assoc())$users[]=$r;
$balances=array();$res=$conn->query("SELECT b.*,u.fullname,t.name leave_type_name FROM leave_balances b JOIN users u ON u.id=b.user_id JOIN leave_types_master t ON t.id=b.leave_type_id ORDER BY b.fiscal_year DESC,u.fullname,t.sort_order LIMIT 100");while($res&&$r=$res->fetch_assoc())$balances[]=$r;
leave_page_start('ตั้งค่าสิทธิ์วันลา','ปรับโควตาเริ่มต้นและกำหนดสิทธิ์รายบุคคลตามปีงบประมาณ','settings');
?>
<div class="leave-grid-equal"><section class="leave-card"><div class="leave-card__head"><div><h2>สิทธิ์เริ่มต้นตามประเภทการลา</h2><p>ค่าเหล่านี้เป็นค่าตั้งต้นของระบบ ควรปรับให้ตรงระเบียบจริงของโรงพยาบาล</p></div></div><div class="leave-card__body"><div class="leave-mini-list"><?php foreach($types as $t):?><form class="leave-mini-item" method="post"><input type="hidden" name="csrf_token" value="<?=leave_e(leave_csrf_token())?>"><input type="hidden" name="action" value="type_quota"><input type="hidden" name="type_id" value="<?=$t['id']?>"><div><strong><?=leave_e($t['name'])?></strong><span><?=leave_e($t['description'])?></span></div><div style="display:flex;gap:7px;align-items:center"><input class="leave-input" style="width:100px" type="number" step="0.5" min="0" name="default_quota_days" value="<?=$t['default_quota_days']!==null?leave_e($t['default_quota_days']):''?>" placeholder="ตามสิทธิ์"><button class="leave-btn leave-btn--sm leave-btn--secondary">บันทึก</button></div></form><?php endforeach;?></div></div></section>
<section class="leave-card"><div class="leave-card__head"><div><h2>กำหนดสิทธิ์รายบุคคล</h2><p>ใช้เมื่อบุคลากรมีสิทธิ์ต่างจากค่าเริ่มต้น</p></div></div><div class="leave-card__body"><form method="post"><input type="hidden" name="csrf_token" value="<?=leave_e(leave_csrf_token())?>"><input type="hidden" name="action" value="balance"><div class="leave-form-grid"><div class="leave-field leave-col-12"><label>บุคลากร</label><select class="leave-select" name="user_id" required><option value="">-- เลือก --</option><?php foreach($users as $u):?><option value="<?=$u['id']?>"><?=leave_e($u['fullname'])?><?=trim((string)$u['department'])!==''?' · '.leave_e($u['department']):''?></option><?php endforeach;?></select></div><div class="leave-field leave-col-6"><label>ปีงบ</label><input class="leave-input" type="number" name="fiscal_year" value="<?=leave_fiscal_year()?>" required></div><div class="leave-field leave-col-6"><label>ประเภท</label><select class="leave-select" name="leave_type_id" required><?php foreach($types as $t):?><option value="<?=$t['id']?>"><?=leave_e($t['name'])?></option><?php endforeach;?></select></div><div class="leave-field leave-col-4"><label>โควตา</label><input class="leave-input" type="number" step="0.5" name="quota_days" value="0"></div><div class="leave-field leave-col-4"><label>ยกมา</label><input class="leave-input" type="number" step="0.5" name="carried_days" value="0"></div><div class="leave-field leave-col-4"><label>ปรับเพิ่ม/ลด</label><input class="leave-input" type="number" step="0.5" name="adjustment_days" value="0"></div><div class="leave-field leave-col-12"><label>หมายเหตุ</label><input class="leave-input" name="note"></div></div><button class="leave-btn leave-btn--primary" style="margin-top:15px;width:100%">บันทึกสิทธิ์รายบุคคล</button></form></div></section></div>
<section class="leave-card"><div class="leave-card__head"><div><h3>สิทธิ์รายบุคคลที่กำหนดไว้</h3><p>แสดง 100 รายการล่าสุด</p></div></div><div class="leave-table-wrap"><table class="leave-table"><thead><tr><th>บุคลากร</th><th>ปีงบ</th><th>ประเภท</th><th>โควตา</th><th>ยกมา</th><th>ปรับ</th><th>รวมสิทธิ์</th><th>หมายเหตุ</th></tr></thead><tbody><?php if(!$balances):?><tr><td colspan="8"><div class="leave-empty">ยังไม่มีการกำหนดสิทธิ์รายบุคคล</div></td></tr><?php endif;?><?php foreach($balances as $b):?><tr><td><?=leave_e($b['fullname'])?></td><td><?=$b['fiscal_year']?></td><td><?=leave_e($b['leave_type_name'])?></td><td><?=leave_format_days($b['quota_days'])?></td><td><?=leave_format_days($b['carried_days'])?></td><td><?=leave_format_days($b['adjustment_days'])?></td><td><strong><?=leave_format_days($b['quota_days']+$b['carried_days']+$b['adjustment_days'])?></strong></td><td><?=leave_e($b['note'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php leave_page_end(); ?>
